  1→//! Dynamic Layer Management
  2→//!
  3→//! Schema validation, path generation, and permit preparation for dynamic layers.
  4→//! Uses PermitIssuer trait — never touches signing keys directly.
  5→
  6→use tracing::{info, warn};
  7→
  8→use crate::state::ScribeState;
  9→use crate::loro_observer;
 10→
 11→use super::LayerUnit;
 12→
 13→/// Handle CreateDynamicLayer message
 14→///
 15→/// **Context**: Lua app calls scribe:create_layer("channels/{id}/messages", "general")
 16→/// **We do**: Validate schema, generate path, issue self-permit, create layer, write __sync_meta
 17→/// **Returns**: Full layer name (bare, without page_id prefix)
 18→pub fn handle_create_dynamic_layer(
 19→    state: &mut ScribeState,
 20→    schema_key: &str,
 21→    layer_id: &str,
 22→    authorized_peers: Option<&[String]>,
 23→) -> Result<String, String> {
 24→    let permit = state.our_permit.as_ref()
 25→        .ok_or_else(|| "No permit available".to_string())?;
 26→
 27→    // Validate schema exists in our permit's dynamic_layer_schemas
 28→    let schemas = permit.dynamic_layer_schemas();
 29→    let schema = schemas
 30→        .get(schema_key)
 31→        .cloned()
 32→        .ok_or_else(|| format!("Schema '{}' not found in permit", schema_key))?;
 33→
 34→    // Generate full layer path with our DID
 35→    // Schema: "channels/{id}/messages" → Path: "channels/{our_did}/{layer_id}/messages"
 36→    let bare_path = generate_dynamic_path(schema_key, &state.our_did, layer_id);
 37→    let full_name = format!("{}/{}", state.page_id, bare_path);
 38→
 39→    // Check if layer already exists
 40→    if state.units.contains_key(&bare_path) {
 41→        info!(layer = %bare_path, "Dynamic layer already exists");
 42→        return Ok(full_name);
 43→    }
 44→
 45→    // Create the layer
 46→    info!(
 47→        page_id = %state.page_id,
 48→        schema = %schema_key,
 49→        layer = %bare_path,
 50→        authorized_peers = ?authorized_peers,
 51→        "Creating dynamic layer"
 52→    );
 53→    let mut unit = LayerUnit::new_empty();
 54→    unit.set_local_only(!state.should_sync_layer(&bare_path));
 55→    unit.is_dynamic = true;
 56→    state.units.insert(bare_path.clone(), unit);
 57→
 58→    // Add all connected subscribers to the new layer
 59→    if let Ok(subs) = state.subscribers.read() {
 60→        for ((did, _), info) in subs.iter() {
 61→            if let Some(unit) = state.units.get(&bare_path) {
 62→                let caps = super::Capabilities { read: true, write: true, sync: true };
 63→                unit.add_subscriber(did.clone(), caps, info.broadcast_tx.clone());
 64→                state.emit_layer_auth_capture(&bare_path, did, "subscriber_added_on_create");
 65→            }
 66→        }
 67→    }
 68→
 69→    // Set up observer for the new layer
 70→    loro_observer::setup_layer_observer(state, &bare_path);
 71→
 72→    // Issue self-signed layer_authority permit (using schema config)
 73→    // Self-permit must be persisted BEFORE __sync_meta entry (which triggers discovery)
 74→    if let Some(ref issuer) = state.permit_issuer {
 75→        let config = schema.permissions.clone();
 76→        let auth_peers = authorized_peers.map(|p| p.to_vec());
 77→        match issuer.issue_layer_authority_permit(
 78→            &state.our_did, &full_name, config, auth_peers, 1,
 79→        ) {
 80→            Ok((_token, _cid)) => {
 81→                info!(layer = %full_name, "Issued self-permit for dynamic layer");
 82→            }
 83→            Err(e) => {
 84→                warn!(layer = %full_name, error = %e, "Failed to issue self-permit for dynamic layer");
 85→            }
 86→        }
 87→    }
 88→
 89→    // Write entry to creator's __sync_meta for node discovery
 90→    {
 91→        use crate::sync::sync_meta;
 92→        let our_did = state.our_did.clone();
 93→        let meta_layer = sync_meta::sync_meta_layer_name(&our_did);
 94→        if state.units.contains_key(&meta_layer) {
 95→            sync_meta::write_sync_meta_entry(state, &our_did, &bare_path, false);
 96→            info!(layer = %bare_path, "Wrote dynamic layer entry to creator's __sync_meta");
 97→        }
 98→    }
 99→
100→    Ok(full_name)
101→}
102→
103→/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
104→///
105→/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
106→/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
107→///
108→/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
109→fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
110→    let parts: Vec<&str> = schema_key.split('/').collect();
111→    let mut result = Vec::new();
112→
113→    if parts.is_empty() {
114→        return format!("{}/{}", our_did, layer_id);
115→    }
116→
117→    // First segment: literal
118→    result.push(parts[0].to_string());
119→
120→    // Insert our DID as the second segment (namespace)
121→    result.push(our_did.to_string());
122→
123→    // Remaining segments: replace {id} with layer_id, keep literals
124→    for part in &parts[1..] {
125→        if *part == "{id}" {
126→            result.push(layer_id.to_string());
127→        } else {
128→            result.push(part.to_string());
129→        }
130→    }
131→
132→    result.join("/")
133→}
134→
135→/// Find matching dynamic schema for a layer received from a peer
136→///
137→/// **Context**: Node receives a new layer from peer. Check if it matches a dynamic schema.
138→/// **Returns**: (schema_key, schema, creator_did) if matched, None otherwise
139→pub fn find_matching_dynamic_schema<'a>(
140→    permit: &'a gurkha::Permit,
141→    layer_name: &str,
142→    page_id: &str,
143→) -> Option<(&'a str, &'a gurkha::DynamicLayerSchema, String)> {
144→    let schemas = permit.dynamic_layer_schemas();
145→    if schemas.is_empty() {
146→        return None;
147→    }
148→
149→    // Strip page_id prefix to get bare layer path
150→    let page_prefix = format!("{}/", page_id);
151→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
152→
153→    let path_parts: Vec<&str> = bare_path.split('/').collect();
154→
155→    // Path must have at least 3 segments: prefix/did/id[/suffix]
156→    if path_parts.len() < 3 {
157→        return None;
158→    }
159→
160→    // Second segment should be a DID (the creator)
161→    let potential_creator = path_parts[1];
162→    if !potential_creator.starts_with("did:") {
163→        return None;
164→    }
165→
166→    // Try each schema pattern
167→    for (schema_key, schema) in schemas {
168→        let pattern_parts: Vec<&str> = schema_key.split('/').collect();
169→
170→        // Dynamic path has one extra segment (DID) compared to pattern
171→        if path_parts.len() != pattern_parts.len() + 1 {
172→            continue;
173→        }
174→
175→        // First segment must match literally
176→        if path_parts[0] != pattern_parts[0] {
177→            continue;
178→        }
179→
180→        // path[2..] must match pattern[1..] (with {id} as wildcard)
181→        let mut matched = true;
182→        for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
183→            if *pat_seg != "{id}" && path_seg != pat_seg {
184→                matched = false;
185→                break;
186→            }
187→        }
188→
189→        if matched {
190→            return Some((schema_key, schema, potential_creator.to_string()));
191→        }
192→    }
193→
194→    None
195→}
