300→/// Handle RemoveLayerAccess message
301→///
302→/// **Context**: Lua app calls scribe:remove_layer_access(layer_name, did)
303→/// **We do**: Validate capability, reject metadata-era revoke path
304→pub fn handle_remove_layer_access(
305→    state: &ScribeState,
306→    layer_name: &str,
307→    did: &str,
308→) -> Result<(), String> {
309→    let permit = state.our_permit.as_ref().ok_or("No permit")?;
310→    if !permit.can_manage_layer_access() {
311→        return Err("No manage_layer_access capability".into());
312→    }
313→
314→    let _ = layer_name;
315→    let _ = did;
316→    Err("RemoveLayerAccess is deprecated; rotate/revoke layer authority permits instead".to_string())
317→}
