  1→//! Typed CRDT operation handlers
  2→//!
  3→//! Handles list, map, and counter operations for Scribe actor.
  4→//! **Broadcast**: Handled automatically by Loro observer after commit()
  5→//!
  6→//! **Path convention**:
  7→//! - Empty path ("") = use layer_name as container name directly (Lua bindings)
  8→//! - Non-empty path = use root map pattern with nested containers (template actions)
  9→
 10→use tracing::{debug, info, instrument};
 11→
 12→use crate::{ScribeError, Result};
 13→use domains::json_to_loro_value;
 14→
 15→use crate::layer_unit::{LayerUnit, find_matching_dynamic_schema};
 16→use crate::state::ScribeState;
 17→use crate::loro_observer;
 18→
 19→// Typed CRDT Operation Handlers
 20→
 21→/// Helper to ensure a layer exists, returns true if layer was newly created.
 22→///
 23→/// **Sync-target auto-subscription**: When a new syncable layer is created and we have
 24→/// a sync_target (owner/viewer mode), the sync_target is auto-added as subscriber.
 25→/// This ensures new dynamic layers propagate to the node via the normal CRDT observer
 26→/// broadcast path — no separate __sync_meta discovery needed.
 27→fn ensure_layer_exists(state: &mut ScribeState, layer_name: &str) -> bool {
 28→    let is_new = !state.units.contains_key(layer_name);
 29→    if is_new {
 30→        let mut unit = LayerUnit::new_empty();
 31→        unit.set_local_only(!state.should_sync_layer(layer_name));
 32→
 33→        // Mark as dynamic if it matches a dynamic schema (node-side detection)
 34→        if let Some(ref permit) = state.our_permit {
 35→            if find_matching_dynamic_schema(permit, layer_name, &state.page_id).is_some() {
 36→                unit.is_dynamic = true;
 37→            }
 38→        }
 39→
 40→        state.units.insert(layer_name.to_string(), unit);
 41→
 42→        // Auto-subscribe sync_target to new syncable layers
 43→        auto_subscribe_sync_target(state, layer_name);
 44→
 45→        debug!(layer = %layer_name, "Created new layer");
 46→    }
 47→
 48→    is_new
 49→}
 50→
 51→/// Auto-subscribe the sync_target to a newly created syncable layer.
 52→///
 53→/// **Context**: Owner/viewer creates a new layer. The sync_target (node) needs to
 54→/// receive data for it. By adding them as subscriber, the Loro observer broadcasts
 55→/// will include them, and the PeerActor sends SyncOffer to the node.
 56→pub(crate) fn auto_subscribe_sync_target(state: &ScribeState, layer_name: &str) {
 57→    if !state.should_sync_layer(layer_name) {
 58→        info!(layer = %layer_name, "auto_subscribe_sync_target: layer not syncable, skipping");
 59→        return;
 60→    }
 61→
 62→    let sync_target_did = match state.sync_config.as_ref() {
 63→        Some(cfg) => match cfg.sync_target.as_deref() {
 64→            Some(did) => did.to_string(),
 65→            None => {
 66→                info!(layer = %layer_name, "auto_subscribe_sync_target: no sync_target in config");
 67→                return;
 68→            }
 69→        },
 70→        None => {
 71→            info!(layer = %layer_name, "auto_subscribe_sync_target: no sync_config");
 72→            return;
 73→        }
 74→    };
 75→
 76→    let sub_count = state.subscribers.read().map(|s| s.len()).unwrap_or(0);
 77→    let broadcast_tx = state.subscribers.read().ok().and_then(|subs| {
 78→        subs.iter()
 79→            .find(|((d, _), _)| d == &sync_target_did)
 80→            .map(|(_, info)| info.broadcast_tx.clone())
 81→    });
 82→
 83→    if broadcast_tx.is_none() {
 84→        info!(
 85→            layer = %layer_name,
 86→            sync_target = %sync_target_did,
 87→            subscriber_count = sub_count,
 88→            "auto_subscribe_sync_target: sync_target not found in subscribers"
 89→        );
 90→        // Log all subscriber DIDs for debugging
 91→        if let Ok(subs) = state.subscribers.read() {
 92→            for ((did, _), _) in subs.iter() {
 93→                info!(layer = %layer_name, subscriber_did = %did, "  existing subscriber");
 94→            }
 95→        }
 96→    }
 97→
 98→    if let (Some(unit), Some(tx)) = (state.units.get(layer_name), broadcast_tx) {
 99→        let caps = crate::layer_unit::Capabilities { read: true, write: true, sync: true };
100→        unit.add_subscriber(sync_target_did.clone(), caps, tx);
101→        info!(layer = %layer_name, target = %sync_target_did, "Auto-subscribed sync_target to new layer");
102→    }
103→}
