105→/// Handle list push operation (append)
106→///
107→/// **Broadcast**: Loro observer triggers broadcast after commit()
108→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
109→#[instrument(skip(state, item), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
110→pub async fn handle_list_push(
111→    state: &mut ScribeState,
112→    layer_name: &str,
113→    path: &str,
114→    item: serde_json::Value,
115→) -> Result<()> {
116→    info!("ListPush operation");
117→
118→    // Ensure layer exists
119→    let is_new_layer = ensure_layer_exists(state, layer_name);
120→
121→    let unit = state.units.get_mut(layer_name)
122→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
123→
124→    if path.is_empty() {
125→        // Lua pattern: use layer_name as container name directly
126→        let list = unit.layer().loro().get_list(layer_name);
127→        let loro_value = json_to_loro_value(&item);
128→        list.push(loro_value)
129→            .map_err(|e| ScribeError::CrdtError(format!("ListPush: {}", e)))?;
130→        unit.layer().commit();
131→    } else {
132→        // Template pattern: use root map with nested path
133→        unit.layer().list_push(path, &item)
134→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
135→    }
136→
137→    unit.mark_dirty();
138→
139→    // Set up observer if new layer (after first write)
140→    if is_new_layer {
141→        loro_observer::setup_layer_observer(state, layer_name);
142→    }
143→
144→    Ok(())
145→}
146→
147→/// Handle list insert operation
148→///
149→/// **Broadcast**: Loro observer triggers broadcast after commit()
150→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
151→#[instrument(skip(state, item), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
152→pub async fn handle_list_insert(
153→    state: &mut ScribeState,
154→    layer_name: &str,
155→    path: &str,
156→    index: usize,
157→    item: serde_json::Value,
158→) -> Result<()> {
159→    info!("ListInsert operation");
160→
161→    let is_new_layer = ensure_layer_exists(state, layer_name);
162→
163→    let unit = state.units.get_mut(layer_name)
164→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
165→
166→    if path.is_empty() {
167→        // Lua pattern: use layer_name as container name directly
168→        let list = unit.layer().loro().get_list(layer_name);
169→        let loro_value = json_to_loro_value(&item);
170→        list.insert(index, loro_value)
171→            .map_err(|e| ScribeError::CrdtError(format!("ListInsert: {}", e)))?;
172→        unit.layer().commit();
173→    } else {
174→        // Template pattern: use root map with nested path
175→        unit.layer().list_insert(path, index, &item)
176→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
177→    }
178→
179→    unit.mark_dirty();
180→
181→    if is_new_layer {
182→        loro_observer::setup_layer_observer(state, layer_name);
183→    }
184→
185→    Ok(())
186→}
187→
188→/// Handle list delete operation
189→///
190→/// **Broadcast**: Loro observer triggers broadcast after commit()
191→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
192→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
193→pub async fn handle_list_delete(
194→    state: &mut ScribeState,
195→    layer_name: &str,
196→    path: &str,
197→    index: usize,
198→) -> Result<()> {
199→    info!("ListDelete operation");
200→
201→    let is_new_layer = ensure_layer_exists(state, layer_name);
202→
203→    let unit = state.units.get_mut(layer_name)
204→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
205→
206→    if path.is_empty() {
207→        // Lua pattern: use layer_name as container name directly
208→        let list = unit.layer().loro().get_list(layer_name);
209→        list.delete(index, 1)
210→            .map_err(|e| ScribeError::CrdtError(format!("ListDelete: {}", e)))?;
211→        unit.layer().commit();
212→    } else {
213→        // Template pattern: use root map with nested path
214→        unit.layer().list_delete(path, index)
215→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
216→    }
217→
218→    unit.mark_dirty();
219→
220→    if is_new_layer {
221→        loro_observer::setup_layer_observer(state, layer_name);
222→    }
223→
224→    Ok(())
225→}
226→
227→/// Handle map insert operation
228→///
229→/// **Broadcast**: Loro observer triggers broadcast after commit()
230→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
231→#[instrument(skip(state, value), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
232→pub async fn handle_map_insert(
233→    state: &mut ScribeState,
234→    layer_name: &str,
235→    path: &str,
236→    key: &str,
237→    value: serde_json::Value,
238→) -> Result<()> {
239→    info!("MapInsert operation");
240→
241→    let is_new_layer = ensure_layer_exists(state, layer_name);
242→
243→    let unit = state.units.get_mut(layer_name)
244→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
245→
246→    if path.is_empty() {
247→        // Lua pattern: use layer_name as container name directly
248→        let map = unit.layer().loro().get_map(layer_name);
249→        let loro_value = json_to_loro_value(&value);
250→        map.insert(key, loro_value)
251→            .map_err(|e| ScribeError::CrdtError(format!("MapInsert: {}", e)))?;
252→        unit.layer().commit();
253→    } else {
254→        // Template pattern: use root map with nested path
255→        unit.layer().map_insert(path, key, &value)
256→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
257→    }
258→
259→    unit.mark_dirty();
260→
261→    if is_new_layer {
262→        loro_observer::setup_layer_observer(state, layer_name);
263→    }
264→
265→    Ok(())
266→}
267→
268→/// Handle map delete operation
269→///
270→/// **Broadcast**: Loro observer triggers broadcast after commit()
271→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
272→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
273→pub async fn handle_map_delete(
274→    state: &mut ScribeState,
275→    layer_name: &str,
276→    path: &str,
277→    key: &str,
278→) -> Result<()> {
279→    info!("MapDelete operation");
280→
281→    let is_new_layer = ensure_layer_exists(state, layer_name);
282→
283→    let unit = state.units.get_mut(layer_name)
284→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
285→
286→    if path.is_empty() {
287→        // Lua pattern: use layer_name as container name directly
288→        let map = unit.layer().loro().get_map(layer_name);
289→        map.delete(key).ok(); // Ignore if key doesn't exist
290→        unit.layer().commit();
291→    } else {
292→        // Template pattern: use root map with nested path
293→        unit.layer().map_delete(path, key)
294→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
295→    }
296→
297→    unit.mark_dirty();
298→
299→    if is_new_layer {
300→        loro_observer::setup_layer_observer(state, layer_name);
301→    }
302→
303→    Ok(())
304→}
