306→/// Handle counter increment operation
307→///
308→/// **Broadcast**: Loro observer triggers broadcast after commit()
309→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
310→pub async fn handle_counter_inc(
311→    state: &mut ScribeState,
312→    layer_name: &str,
313→    path: &str,
314→    amount: i64,
