321→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
322→
323→    unit.layer().counter_inc(path, amount)
324→        .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
325→
326→    unit.mark_dirty();
327→
328→    if is_new_layer {
329→        loro_observer::setup_layer_observer(state, layer_name);
