  1→//! Permit parsing and permission checking for Scribe actor
  2→//!
  3→//! Handles:
  4→//! - Layer access control (read/write permissions)
  5→//! - Sync policy extraction and enforcement
  6→//! - Pattern-based permission rules
  7→//! - Static layer extraction for pre-creation
  8→//!
  9→//! ## Thin Wrapper Pattern
 10→//!
 11→//! The `PermitContext` struct is a thin wrapper around `gurkha::Permit` that adds
 12→//! page_id and our_did context for method calls. All actual logic delegates to gurkha.
 13→
 14→use tracing::{debug, instrument, trace};
 15→
 16→use crate::state::ScribeState;
 17→use crate::{Result, ScribeError};
 18→
 19→// PermitContext - Thin Wrapper around gurkha::Permit
 20→
 21→/// Thin wrapper around gurkha::Permit with page/DID context
 22→///
 23→/// **Context**: Provides convenient access to permit methods with pre-bound page_id and our_did.
 24→/// **Design**: Stores gurkha::Permit directly, delegates all logic to it.
 25→///
 26→/// **Usage**:
 27→/// ```ignore
 28→/// let ctx = PermitContext::from_token(permit, page_id, our_did)?;
 29→/// if ctx.can_write_layer("orders") { ... }
 30→/// if ctx.should_sync_layer("messages") { ... }
 31→/// ```
 32→#[derive(Debug, Clone)]
 33→pub struct PermitContext {
 34→    /// The parsed permit - source of truth for all access checks
 35→    permit: gurkha::Permit,
 36→    /// Page ID (for pattern expansion)
 37→    page_id: String,
 38→    /// Our DID (for pattern expansion with {aud})
 39→    our_did: String,
 40→}
 41→
 42→impl PermitContext {
 43→    /// Parse permit and create context with page/DID binding
 44→    #[instrument(skip(token))]
 45→    pub fn from_token(token: &str, page_id: &str, our_did: &str) -> Result<Self> {
 46→        let permit = gurkha::Permit::from_token(token)
 47→            .map_err(|e| ScribeError::PermitError(format!("Failed to parse permit: {:?}", e)))?;
 48→
 49→        debug!(
 50→            role = ?permit.relationship(),
 51→            is_owner = permit.is_owner(),
 52→            is_host = permit.is_host(),
 53→            layers = permit.layers().len(),
 54→            patterns = permit.layer_patterns().len(),
 55→            "PermitContext created (thin wrapper)"
 56→        );
 57→
 58→        Ok(Self {
 59→            permit,
 60→            page_id: page_id.to_string(),
 61→            our_did: our_did.to_string(),
 62→        })
 63→    }
 64→
 65→    /// Check if layer can be written to
 66→    /// Delegates to gurkha::Permit::can_write_layer()
 67→    pub fn can_write_layer(&self, layer_name: &str) -> bool {
 68→        self.permit
 69→            .can_write_layer(layer_name, &self.page_id, &self.our_did)
 70→    }
 71→
 72→    /// Check if layer can be read/synced
 73→    /// Delegates to gurkha::Permit::can_read_layer()
 74→    pub fn can_read_layer(&self, layer_name: &str) -> bool {
 75→        self.permit
 76→            .can_read_layer(layer_name, &self.page_id, &self.our_did)
 77→    }
 78→
 79→    /// Check if layer should sync (not local-only)
 80→    /// Delegates to gurkha::Permit::should_sync_layer()
 81→    pub fn should_sync_layer(&self, layer_name: &str) -> bool {
 82→        self.permit
 83→            .should_sync_layer(layer_name, &self.page_id, &self.our_did)
 84→    }
 85→
 86→    /// Check if layer should send full snapshot instead of incremental
 87→    pub fn should_send_full_snapshot(&self, layer_name: &str) -> bool {
 88→        self.permit
 89→            .sync_facts()
 90→            .send_full_snapshot
 91→            .contains(&layer_name.to_string())
 92→    }
 93→
 94→    /// Check if layer is local-only (never synced)
 95→    pub fn is_layer_local_only(&self, layer_name: &str) -> bool {
 96→        self.permit
 97→            .sync_facts()
 98→            .local_only
 99→            .contains(&layer_name.to_string())
100→    }
101→
102→    /// Get the raw permit token
103→    pub fn raw_token(&self) -> &str {
104→        self.permit.raw_token()
105→    }
106→
107→    /// Get page ID
108→    pub fn page_id(&self) -> &str {
109→        &self.page_id
110→    }
111→
112→    /// Get our DID
113→    pub fn our_did(&self) -> &str {
114→        &self.our_did
115→    }
116→
117→    /// Get the underlying permit for direct access
118→    pub fn permit(&self) -> &gurkha::Permit {
119→        &self.permit
120→    }
121→
122→    /// Check if this is an owner permit
123→    pub fn is_owner(&self) -> bool {
124→        self.permit.is_owner()
125→    }
126→
127→    /// Check if this is a host/node permit
128→    pub fn is_host(&self) -> bool {
129→        self.permit.is_host()
130→    }
131→
132→    /// Get static layers (fully expanded, no wildcards) for pre-creation
133→    pub fn static_layers(&self) -> Vec<String> {
134→        self.permit.static_layers(&self.page_id, &self.our_did)
135→    }
136→}
137→
138→/// Simple glob pattern matching for layer names
139→///
140→/// **Supported patterns:**
141→/// - `*` at end: prefix match (e.g., "*:order" matches anything ending with ":order")
142→/// - `*` at start: suffix match (e.g., "did:*" matches anything starting with "did:")
143→/// - Exact match otherwise
144→pub fn glob_match(pattern: &str, name: &str) -> bool {
145→    if pattern == "*" {
146→        true
147→    } else if pattern.starts_with('*') {
148→        // Suffix match: "*:order" matches "did:key:abc:order"
149→        name.ends_with(&pattern[1..])
150→    } else if pattern.ends_with('*') {
151→        // Prefix match: "app:*" matches "app:shop"
152→        name.starts_with(&pattern[..pattern.len() - 1])
153→    } else {
154→        // Exact match
155→        pattern == name
156→    }
157→}
158→
159→// Permission Checking
160→
161→/// Scribe permission checking methods
162→pub struct Permissions;
163→
164→impl Permissions {
165→    /// Check if layer is local_only (never synced)
166→    pub fn is_local_only(layer_name: &str) -> bool {
167→        // Check all subscribers' policies - if ANY marks it local_only, treat as such
168→        // Actually, local_only is typically a page-level setting, not per-peer
169→        // For simplicity, we'll check the layer name
170→        layer_name == "user_content_doc"
171→    }
172→
173→    /// Check if peer can write to layer
174→    ///
175→    /// **Context**: Remote peer is trying to write to this layer
176→    /// **We check**:
177→    /// 1. Peer is a subscriber with write permission via permit.can_write_layer()
178→    /// 2. OR peer is our sync_target (owner/viewer mode - trust sync source)
179→    /// 3. OR peer has a stored permit with write access (node mode - permit-based sync auth)
180→    /// 4. OR our permit's dynamic_layer_schemas grant write for peer's role (dynamic layers)
181→    ///
182→    /// **Security**: For pattern-based layers, gurkha::Permit validates that:
183→    /// - The layer name matches the expanded pattern
184→    /// - Patterns with {aud} expand to the peer's actual DID (namespace enforcement)
185→    pub fn can_write(state: &ScribeState, peer: &(String, String), layer_name: &str) -> bool {
186→        let peer_did = &peer.0;
187→
188→        // 0. Protocol layers: __sync_meta:{peer_did} allows writes from the named peer
189→        //
190→        // **Context**: Each peer owns their __sync_meta layer and writes discovery entries.
191→        // The node also writes status entries (locally, no remote check needed).
192→        // When the peer sends SyncOffer for their own __sync_meta, we allow it.
193→        if crate::sync::sync_meta::is_sync_meta_layer(layer_name) {
194→            if let Some(meta_did) = crate::sync::sync_meta::extract_peer_did(layer_name) {
195→                if meta_did == peer_did {
196→                    debug!(user_did = %peer_did, layer = %layer_name, "Write allowed: peer owns this __sync_meta layer");
197→                    state.emit_permission_check_capture(
198→                        layer_name,
199→                        peer_did,
200→                        "allowed",
201→                        "sync_meta_owner",
202→                    );
203→                    return true;
204→                }
205→            }
206→        }
207→
208→        // 1. Check if peer is a subscriber with write permission
209→        if let Ok(subs) = state.subscribers.read() {
210→            if let Some(info) = subs.get(peer) {
211→                // Use permit's can_write_layer which handles both fixed and pattern-based
212→                if info.can_write_layer(layer_name, &state.page_id) {
213→                    trace!(
214→                        user_did = %peer_did,
215→                        layer = %layer_name,
216→                        "Write allowed via subscriber permit"
217→                    );
218→                    state.emit_permission_check_capture(
219→                        layer_name,
220→                        peer_did,
221→                        "allowed",
222→                        "subscriber_permit",
223→                    );
224→                    return true;
225→                }
226→            }
227→        }
228→
229→        // 2. Owner/Viewer mode: trust data from our sync_target (the node we sync with)
230→        // This allows receiving sync updates from the node without explicit subscription
231→        if let Some(ref config) = state.sync_config {
232→            if let Some(ref sync_target) = config.sync_target {
233→                if peer_did == sync_target {
234→                    debug!(user_did = %peer_did, layer = %layer_name, "Write allowed from sync_target");
235→                    state.emit_permission_check_capture(
236→                        layer_name,
237→                        peer_did,
238→                        "allowed",
239→                        "sync_target",
240→                    );
241→                    return true;
242→                }
243→            }
244→        }
245→
246→        // 3. Node mode: check stored permit for write access (permit-based auth)
247→        if let Some(ref resolver) = state.peer_resolver {
248→            if let Some(permit_token) = resolver.load_user_permit(peer_did) {
249→                // Parse permit and check write permissions
250→                if let Ok(permit) = gurkha::Permit::from_token(&permit_token) {
251→                    if permit.can_write_layer(layer_name, &state.page_id, peer_did) {
252→                        debug!(user_did = %peer_did, layer = %layer_name, "Write allowed via stored permit");
253→                        state.emit_permission_check_capture(
254→                            layer_name,
255→                            peer_did,
256→                            "allowed",
257→                            "stored_permit",
258→                        );
259→                        return true;
260→                    }
261→                }
262→            }
263→        }
264→
265→        // 4. Node mode: check our permit's dynamic_layer_schemas permissions
266→        //
267→        // **Context**: Dynamic layers (e.g. channels/did:key:alice/project-x/messages)
268→        // aren't in the peer's page permit (they contain another user's DID in the path).
269→        // The node's own permit has dynamic_layer_schemas with permissions that grant
270→        // write access to all peers. We check the schema permissions directly.
271→        if let Some(ref our_permit) = state.our_permit {
272→            if gurkha::matches_dynamic_schema(
273→                our_permit,
274→                layer_name,
275→                &state.page_id,
276→                "write",
277→            ) {
278→                debug!(
279→                    user_did = %peer_did,
280→                    layer = %layer_name,
281→                    "Write allowed via dynamic_layer_schema check"
282→                );
283→                state.emit_permission_check_capture(
284→                    layer_name,
285→                    peer_did,
286→                    "allowed",
287→                    "dynamic_schema",
288→                );
289→                return true;
290→            }
291→        }
292→
293→        state.emit_permission_check_capture(layer_name, peer_did, "denied", "all_paths_failed");
294→        false
295→    }
296→
297→    /// Check if we (local user) can write to a layer
298→    ///
299→    /// **Context**: Local Lua/UI is trying to modify a layer
300→    /// **We check**: Delegates to ScribeState::can_write_layer()
301→    ///
302→    /// **Security**: Ensures local writes respect our permit constraints
303→    /// (e.g., viewer can only write to their namespaced layers)
304→    pub fn can_local_write(state: &ScribeState, layer_name: &str) -> bool {
305→        state.can_write_layer(layer_name)
306→    }
307→}
