216→/// Prepare page for viewer (Node mode) - delegate permit, filter layers, encrypt for transit
217→#[instrument(skip(store, viewer_encryption_key, node_signing_key, node_secret_key), fields(page_id = %page_id))]
218→pub async fn prepare_page_for_viewer(
219→    store: &RedbStore,
220→    page_id: &str,
221→    viewer_public_key: &str,
222→    viewer_encryption_key: &[u8; 32],
223→    node_signing_key: &[u8; 32],
224→    node_secret_key: &[u8; 32],
225→) -> Result<PreparedPage> {
226→    // 1. Find the page
227→    let page_data = store.find_page_by_id(page_id)?
228→        .ok_or_else(|| ButlerError::page_not_found(page_id))?;
229→
230→    // 2. Get node's permit from the page - clone to avoid borrow issues
231→    let node_permit = page_data.get_permit()
232→        .ok_or_else(|| ButlerError::permit_not_found(
233→            &format!("Node permit not found for page {}", page_id)
234→        ))?
235→        .clone();
236→
237→    // 3. Parse permit to get local_only layers (for filtering)
238→    let permit = gurkha::Permit::from_token(&node_permit)
239→        .map_err(|e| ButlerError::permit_error(format!("Failed to parse permit: {:?}", e)))?;
240→    let local_only_layers: Vec<String> = permit.local_only_layers();
241→
242→    // 4. Issue page permit for viewer via gurkha
243→    let (viewer_permit, _cid) = gurkha::delegate_page(
244→        node_signing_key,
245→        &node_permit,
246→        "viewer",  // template_key from PAGE_TEMPLATE.delegation.viewer
247→        viewer_public_key,
248→    ).await.map_err(|e| ButlerError::permit_error(format!("Failed to issue viewer permit: {}", e)))?;
249→
250→    // 4a. Parse viewer permit for pattern-based filtering
251→    let viewer_permit_parsed = gurkha::Permit::from_token(&viewer_permit)
252→        .map_err(|e| ButlerError::permit_error(format!("Failed to parse viewer permit: {:?}", e)))?;
253→
254→    // 5. Decrypt AES key using node's secret key
255→    let aes_key = herald::decrypt(node_secret_key, &page_data.meta.encrypted_key)
256→        .map_err(|e| ButlerError::Encryption(format!("Failed to decrypt AES key: {}", e)))?;
257→
258→    let aes_key_arr: [u8; 32] = aes_key.try_into()
259→        .map_err(|_| ButlerError::Encryption("Invalid AES key length".to_string()))?;
260→
261→    // 5a. Auto-create viewer's namespace layers from layer_patterns with create=true
262→    // Pattern like "{page_id}/orders/{aud}" with create=true means viewer gets their own layer
263→    let viewer_aud_b64 = viewer_permit_parsed.audience().unwrap_or("");
264→    // Convert base64 audience to DID format for layer naming consistency
265→    let viewer_did = herald::Identity::did_from_base64_pubkey(viewer_aud_b64)
266→        .unwrap_or_else(|_| viewer_aud_b64.to_string());
267→
268→    for (pattern, config) in viewer_permit_parsed.layer_patterns() {
269→        if config.create {
270→            // Expand pattern with actual values
271→            // Use DID format for {aud} so layer names are human-readable
272→            let expanded = pattern
273→                .replace("{page_id}", page_id)
274→                .replace("{aud}", &viewer_did);
275→
276→            // Only create if pattern doesn't have wildcards after expansion
277→            // e.g., "{page_id}/orders/{aud}" → "shop123/orders/did:key:xyz" (createable)
278→            // e.g., "{page_id}/*/*" → "shop123/*/*" (not createable, has wildcards)
279→            if !expanded.contains('*') && !expanded.contains('{') {
280→                // Check if layer already exists
281→                if store.get_layer(page_id, &expanded)?.is_none() {
282→                    tracing::info!(
283→                        "Auto-creating viewer namespace layer '{}' for viewer {}",
284→                        expanded, viewer_did
285→                    );
286→                    // Create empty LoroDoc for the layer
287→                    let empty_doc = loro::LoroDoc::new();
288→                    let empty_bytes = empty_doc.export(loro::ExportMode::Snapshot)
289→                        .map_err(|e| ButlerError::Database(format!("Failed to create empty layer: {}", e)))?;
290→                    let encrypted = herald::encrypt_symmetric(&aes_key_arr, &empty_bytes)
291→                        .map_err(|e| ButlerError::Encryption(
292→                            format!("Failed to encrypt auto-created layer {}: {}", expanded, e)
293→                        ))?;
294→                    store.put_layer(page_id, &expanded, &encrypted)?;
295→                }
296→            }
297→        }
298→    }
299→
300→    // 6. Get and decrypt all layers, filtering by viewer's permit access
301→    let encrypted_layers = store.get_all_layers(page_id)?;
302→    let mut decrypted_layers = Vec::new();
303→
304→    for (layer_name, encrypted_bytes) in encrypted_layers {
305→        // Skip local_only layers (e.g., user_content_doc) - not synced to viewer
306→        if local_only_layers.iter().any(|l| l == &layer_name) {
307→            tracing::debug!("Filtering out local_only layer '{}'", layer_name);
308→            continue;
309→        }
310→
311→        // Filter by viewer's permit patterns
312→        // Only send layers the viewer has access to sync
313→        // can_access_layer accepts bare names (strips page_id/ prefix internally)
314→        if !gurkha::can_access_layer(&viewer_permit_parsed, &layer_name, "sync") {
315→            tracing::debug!(
316→                "Filtering out layer '{}' - viewer {} doesn't have sync access",
317→                layer_name, viewer_did
318→            );
319→            continue;
320→        }
321→
322→        let decrypted_bytes = herald::decrypt_symmetric(&aes_key_arr, &encrypted_bytes)
323→            .map_err(|e| ButlerError::Encryption(
324→                format!("Failed to decrypt layer {}: {}", layer_name, e)
325→            ))?;
326→        decrypted_layers.push((layer_name, decrypted_bytes));
327→    }
328→
329→    // 7. Generate ephemeral keypair and encrypt layers for transit
330→    let (ephemeral_secret, ephemeral_public) = herald::generate_ephemeral_keypair();
331→
332→    // Derive transit key from ECDH
333→    let shared_secret = herald::ecdh(&ephemeral_secret, viewer_encryption_key);
334→    let transit_key = herald::derive_key(&shared_secret, None, b"herald-transit-v1");
335→
336→    // Encrypt each layer with transit key
337→    let mut transit_layers = Vec::with_capacity(decrypted_layers.len());
338→    for (layer_name, plaintext) in decrypted_layers {
339→        let encrypted = herald::encrypt_symmetric(&transit_key, &plaintext)
340→            .map_err(|e| ButlerError::Encryption(
341→                format!("Failed to transit-encrypt layer {}: {}", layer_name, e)
342→            ))?;
343→        transit_layers.push((layer_name, encrypted));
344→    }
345→
346→    Ok(PreparedPage {
347→        meta: page_data.meta,
348→        permit: viewer_permit,
349→        owner_permit: node_permit,  // Node's permit - used for sync authorization
350→        ephemeral_public,
351→        layers: transit_layers,
352→    })
353→}
