  1→//! Layer Unit — Per-layer compute unit
  2→//!
  3→//! Consolidates all per-layer state (LoroDoc, dirty flag, authorization config,
  4→//! per-subscriber state, observer subscription) into a single struct. Makes Scribe
  5→//! a thin router over LayerUnit instances.
  6→//!
  7→//! ## Authorization model
  8→//!
  9→//! Each LayerUnit owns its subscribers and their capabilities. Authorization is
 10→//! checked at broadcast time using per-subscriber state, not an eagerly-populated
 11→//! HashSet. The `subscribers` map is `Arc<RwLock<...>>` so the observer async task
 12→//! can read it for broadcast decisions.
 13→//!
 14→//! Also contains dynamic layer management (schema validation, permit preparation).
 15→
 16→mod dynamic;
 17→
 18→pub use dynamic::{
 19→    handle_create_dynamic_layer, find_matching_dynamic_schema,
 20→    handle_add_layer_access, handle_remove_layer_access,
 21→};
 22→
 23→use std::collections::HashMap;
 24→use std::sync::{Arc, RwLock};
 25→use std::time::{Duration, Instant};
 26→
 27→use tokio::sync::mpsc;
 28→
 29→use domains::Layer;
 30→
 31→use crate::BroadcastPayload;
 32→
 33→// === Capability types ===
 34→
 35→/// Cached capabilities from a layer permit
 36→///
 37→/// **Context**: Parsed from layer permit at subscription time.
 38→/// Each field maps to a specific authorization check.
 39→#[derive(Debug, Clone, Default)]
 40→pub struct Capabilities {
 41→    /// Can read layer data (receive broadcasts)
 42→    pub read: bool,
 43→    /// Can write to layer (send updates)
 44→    pub write: bool,
 45→    /// Can sync (bidirectional replication)
 46→    pub sync: bool,
 47→}
 48→
 49→/// Layer-level configuration derived from permit
 50→///
 51→/// **Context**: Set once at layer creation, describes our own capabilities
 52→/// for this layer (viewer side) or default capabilities (node side).
 53→#[derive(Debug, Clone)]
 54→pub struct LayerConfig {
 55→    /// Our capabilities for this layer
 56→    pub capabilities: Capabilities,
 57→    /// sync: false — never broadcast to peers
 58→    pub is_local_only: bool,
 59→}
 60→
 61→impl Default for LayerConfig {
 62→    fn default() -> Self {
 63→        Self {
 64→            capabilities: Capabilities { read: true, write: true, sync: true },
 65→            is_local_only: false,
 66→        }
 67→    }
 68→}
 69→
 70→/// Per-subscriber state within a LayerUnit
 71→///
 72→/// **Context**: Tracks what each subscriber can do with this specific layer.
 73→/// Created when a peer subscribes and presents a layer permit.
 74→pub struct LayerSubscriber {
 75→    /// What this subscriber can do (from the layer permit we issued)
 76→    pub capabilities: Capabilities,
 77→    /// Their consent token (authorizes us to push updates to them)
 78→    /// None until they send LayerConsent back
 79→    pub consent_token: Option<String>,
 80→    /// Their last known version vector for incremental sync
 81→    pub version_vector: Vec<u8>,
 82→    /// Channel to send broadcasts to this subscriber
 83→    pub broadcast_tx: mpsc::Sender<BroadcastPayload>,
 84→}
 85→
 86→/// Per-layer compute unit — owns all state for a single layer
 87→///
 88→/// **Design**: Self-contained authorization and broadcast. Scribe routes
 89→/// messages to LayerUnits; each unit knows its subscribers and their capabilities.
 90→pub struct LayerUnit {
 91→    // === CRDT ===
 92→    /// The CRDT document
 93→    layer: Layer,
 94→    /// Needs flush to storage?
 95→    dirty: bool,
 96→    /// Loro observer subscription (dropped = unsubscribed)
 97→    loro_sub: Option<loro::Subscription>,
 98→
 99→    // === Authorization (from permit) ===
100→    /// Cached layer configuration (our capabilities, local-only flag)
101→    config: LayerConfig,
102→    /// Raw permit token (viewer side — the permit node gave us)
103→    permit_token: Option<String>,
104→    /// Created via dynamic_layer_schema (not static template)
105→    pub is_dynamic: bool,
106→
107→    // === Subscriber state ===
108→    /// Per-subscriber state (did → subscriber)
109→    /// Arc<RwLock> because the observer async task needs shared read access
110→    subscribers: Arc<RwLock<HashMap<String, LayerSubscriber>>>,
111→
112→    // === Lifecycle ===
113→    /// Last time this layer was accessed (for cold/warm eviction)
114→    last_accessed: Instant,
115→}
116→
117→impl LayerUnit {
118→    /// Create a LayerUnit wrapping an existing layer
119→    pub fn new(layer: Layer) -> Self {
120→        Self {
121→            layer,
122→            dirty: false,
123→            loro_sub: None,
124→            config: LayerConfig::default(),
125→            permit_token: None,
126→            is_dynamic: false,
127→            subscribers: Arc::new(RwLock::new(HashMap::new())),
128→            last_accessed: Instant::now(),
129→        }
130→    }
131→
132→    /// Create a LayerUnit with an empty LoroDoc
133→    pub fn new_empty() -> Self {
134→        Self::new(Layer::new())
135→    }
136→
137→    /// Create a LayerUnit with specific config
138→    pub fn with_config(layer: Layer, config: LayerConfig) -> Self {
139→        let is_local_only = config.is_local_only;
140→        let mut unit = Self::new(layer);
141→        unit.config = config;
142→        // Keep is_local_only in sync for backward compat during migration
143→        unit.config.is_local_only = is_local_only;
144→        unit
145→    }
146→
147→    // === Layer access ===
148→
149→    /// Get a reference to the inner Layer
150→    pub fn layer(&self) -> &Layer {
151→        &self.layer
152→    }
153→
154→    /// Get a mutable reference to the inner Layer
155→    pub fn layer_mut(&mut self) -> &mut Layer {
156→        &mut self.layer
157→    }
158→
159→    /// Replace the inner layer (e.g. snapshot restore)
160→    pub fn replace_layer(&mut self, layer: Layer) {
161→        self.layer = layer;
162→        self.touch();
163→    }
164→
165→    // === Config ===
166→
167→    /// Get the layer configuration
168→    pub fn config(&self) -> &LayerConfig {
169→        &self.config
170→    }
171→
172→    /// Set the layer configuration
173→    pub fn set_config(&mut self, config: LayerConfig) {
174→        self.config = config;
175→    }
176→
177→    /// Get the raw permit token (viewer side)
178→    pub fn permit_token(&self) -> Option<&str> {
179→        self.permit_token.as_deref()
180→    }
181→
182→    /// Set the raw permit token (viewer side)
183→    pub fn set_permit_token(&mut self, token: String) {
184→        self.permit_token = Some(token);
185→    }
186→
187→    // === Dirty tracking ===
188→
189→    /// Mark this layer as needing persistence
190→    pub fn mark_dirty(&mut self) {
191→        self.dirty = true;
192→    }
193→
194→    /// Check if this layer needs persistence
195→    pub fn is_dirty(&self) -> bool {
196→        self.dirty
197→    }
198→
199→    /// Clear the dirty flag without exporting
200→    pub fn clear_dirty(&mut self) {
201→        self.dirty = false;
202→    }
203→
204→    /// Export snapshot if dirty, clear flag. Returns None if clean.
205→    pub fn take_dirty_snapshot(&mut self) -> Option<Vec<u8>> {
206→        if self.dirty {
207→            self.dirty = false;
208→            Some(self.layer.export_snapshot())
209→        } else {
210→            None
211→        }
212→    }
213→
214→    // === Metadata ===
215→
216→    /// Check if this layer is local-only (sync: false)
217→    pub fn is_local_only(&self) -> bool {
218→        self.config.is_local_only
219→    }
220→
221→    /// Set the local-only flag
222→    pub fn set_local_only(&mut self, val: bool) {
223→        self.config.is_local_only = val;
224→    }
225→
226→    /// Check if this layer was created dynamically
227→    pub fn is_dynamic(&self) -> bool {
228→        self.is_dynamic
229→    }
230→
231→    // === Observer lifecycle ===
232→
233→    /// Check if this layer has an active Loro observer
234→    pub fn has_observer(&self) -> bool {
235→        self.loro_sub.is_some()
236→    }
237→
238→    /// Set the Loro observer subscription
239→    pub fn set_observer(&mut self, sub: loro::Subscription) {
240→        self.loro_sub = Some(sub);
241→    }
242→
243→    /// Drop the observer (unsubscribes from Loro)
244→    pub fn clear_observer(&mut self) {
245→        self.loro_sub = None;
246→    }
247→
248→    // === Subscriber management ===
249→
250→    /// Get shared reference to subscribers (for observer to clone the Arc)
251→    pub fn subscribers(&self) -> &Arc<RwLock<HashMap<String, LayerSubscriber>>> {
252→        &self.subscribers
253→    }
254→
255→    /// Add a subscriber with their capabilities and broadcast channel
256→    pub fn add_subscriber(
257→        &self,
258→        did: String,
259→        capabilities: Capabilities,
260→        broadcast_tx: mpsc::Sender<BroadcastPayload>,
261→    ) {
262→        if let Ok(mut subs) = self.subscribers.write() {
263→            subs.insert(did, LayerSubscriber {
264→                capabilities,
265→                consent_token: None,
266→                version_vector: Vec::new(),
267→                broadcast_tx,
268→            });
269→        }
270→    }
271→
272→    /// Remove a subscriber, returning their state if present
273→    pub fn remove_subscriber(&self, did: &str) -> Option<LayerSubscriber> {
274→        if let Ok(mut subs) = self.subscribers.write() {
275→            subs.remove(did)
276→        } else {
277→            None
278→        }
279→    }
280→
281→    /// Set consent token for a subscriber (authorizes us to push to them)
282→    ///
283→    /// **Context**: Viewer sent LayerConsent back after receiving LayerSync.
284→    pub fn set_consent(&self, did: &str, consent_token: String) {
285→        if let Ok(mut subs) = self.subscribers.write() {
286→            if let Some(sub) = subs.get_mut(did) {
287→                sub.consent_token = Some(consent_token);
288→            }
289→        }
290→    }
291→
292→    /// Update a subscriber's version vector after successful broadcast
293→    pub fn update_subscriber_vector(&self, did: &str, vector: Vec<u8>) {
294→        if let Ok(mut subs) = self.subscribers.write() {
295→            if let Some(sub) = subs.get_mut(did) {
296→                sub.version_vector = vector;
297→            }
298→        }
299→    }
300→
301→    /// Check if any subscribers are connected
302→    pub fn has_subscribers(&self) -> bool {
303→        self.subscribers.read()
304→            .map(|subs| !subs.is_empty())
305→            .unwrap_or(false)
306→    }
307→
308→    // === Authorization checks ===
309→
310→    /// Can we accept a write from this DID?
311→    ///
312→    /// **Context**: Node checks this when receiving an update from a peer.
313→    /// The peer must be a subscriber with write capability.
314→    pub fn can_accept_write_from(&self, did: &str) -> bool {
315→        self.subscribers.read()
316→            .map(|subs| {
317→                subs.get(did)
318→                    .map(|s| s.capabilities.write)
319→                    .unwrap_or(false)
320→            })
321→            .unwrap_or(false)
322→    }
323→
324→    /// Can we push updates to this DID?
325→    ///
326→    /// **Context**: Checked at broadcast time. Subscriber must have read
327→    /// capability and have given consent.
328→    pub fn can_push_to(&self, did: &str) -> bool {
329→        self.subscribers.read()
330→            .map(|subs| {
331→                subs.get(did)
332→                    .map(|s| s.capabilities.read)
333→                    .unwrap_or(false)
334→            })
335→            .unwrap_or(false)
336→    }
337→
338→    /// Can WE write to this layer locally? (viewer side check)
339→    pub fn can_local_write(&self) -> bool {
340→        self.config.capabilities.write
341→    }
342→
343→    // === CRDT operations ===
344→
345→    /// Export an incremental update for a specific subscriber
346→    ///
347→    /// **Context**: Uses the subscriber's last known version vector.
348→    /// Falls back to full snapshot if no vector cached or export fails.
349→    pub fn export_update_for(&self, did: &str) -> Vec<u8> {
350→        let their_vector = self.subscribers.read().ok().and_then(|subs| {
351→            subs.get(did).and_then(|s| {
352→                if s.version_vector.is_empty() { None } else { Some(s.version_vector.clone()) }
353→            })
354→        });
355→
356→        if let Some(vector) = their_vector {
357→            self.layer.export_updates(&vector)
358→                .unwrap_or_else(|_| self.layer.export_snapshot())
359→        } else {
360→            self.layer.export_snapshot()
361→        }
362→    }
363→
364→    // === Lifecycle ===
365→
366→    /// Update last_accessed timestamp
367→    pub fn touch(&mut self) {
368→        self.last_accessed = Instant::now();
369→    }
370→
371→    /// Check if this layer is cold (no access for `threshold` duration)
372→    pub fn is_cold(&self, threshold: Duration) -> bool {
373→        self.last_accessed.elapsed() > threshold
374→    }
375→
376→}
