618→        let snapshot = unit.export_update_for("did:key:alice");
619→        assert!(!snapshot.is_empty());
620→
621→        // Add subscriber with empty VV → full snapshot
622→        let caps = Capabilities { read: true, write: true, sync: true };
623→        unit.add_subscriber("did:key:alice".to_string(), caps, make_tx());
624→        let snapshot2 = unit.export_update_for("did:key:alice");
625→        assert!(!snapshot2.is_empty());
626→
627→        // Set a VV → incremental export
628→        let current_vv = unit.layer().version_vector();
