233→        if !Permissions::can_write(state, peer, &ctx.layer_name) {
234→            return ApplyOutcome::Rejected {
235→                reason: "Permission denied: cannot write to layer".to_string(),
236→            };
237→        }
238→    }
239→
240→    // Step 3: Extract ops for validation (using optimized pre-commit method)
241→    let extracted_ops = if ctx.should_validate {
242→        // Use Layer::extract_ops_from_bytes (5-10x faster than old fork+diff)
243→        match Layer::extract_ops_from_bytes(update) {
244→            Ok(ops) => Some(ops),
245→            Err(e) => {
246→                // Log extraction failure - validation will proceed with empty ops
247→                // This could mask invalid updates, so log at warn level
248→                warn!(layer = %ctx.layer_name, error = %e, "Failed to extract ops from update, proceeding with empty ops");
