250→            }
251→        }
252→    } else {
253→        None
254→    };
255→
256→    // Step 4: Validate with Lua (if needed)
257→    if ctx.should_validate {
258→        if let Err(e) = validate_update_with_context(state, ctx, &extracted_ops).await {
259→            return ApplyOutcome::Rejected { reason: e };
260→        }
261→    }
262→
263→    // Step 5: Create layer if needed (remote only)
264→    let created_layer = if ctx.is_new_layer {
265→        if ctx.is_remote {
266→            create_layer_from_peer(state, &ctx.layer_name);
267→            true
268→        } else {
269→            return ApplyOutcome::Rejected {
270→                reason: "Layer not found".to_string(),
271→            };
272→        }
273→    } else {
274→        false
275→    };
276→
277→    // Step 6: Apply CRDT update
278→    if let Err(e) = apply_crdt_update(state, &ctx.layer_name, update, ctx.from_peer.clone()) {
279→        return ApplyOutcome::Rejected { reason: e };
280→    }
281→
282→    ApplyOutcome::Applied {
283→        layer_name: ctx.layer_name.clone(),
284→        ops: extracted_ops.unwrap_or_default(),
285→        created_layer,
286→    }
287→}
