215→        if !unit.can_push_to(user_did) {
216→            continue;
217→        }
218→
219→        let layer = unit.layer();
220→
221→        let data = if let Some(their_vector) = peer_vectors.get(layer_name) {
222→            if their_vector.is_empty() {
223→                layer.export_snapshot()
224→            } else {
225→                match layer.export_updates(their_vector) {
226→                    Ok(updates) if updates.is_empty() => {
227→                        debug!(user_did = %user_did, layer = %layer_name, "No new updates");
228→                        continue;
229→                    }
230→                    Ok(updates) => updates,
231→                    Err(e) => {
232→                        warn!(error = %e, layer = %layer_name, "Failed incremental export, using snapshot");
233→                        layer.export_snapshot()
234→                    }
235→                }
236→            }
237→        } else {
238→            layer.export_snapshot()
239→        };
240→
241→        let state_vector = layer.version_vector();
242→
243→        if data.is_empty() || state_vector.len() <= 1 {
244→            debug!(user_did = %user_did, layer = %layer_name, "Skipping empty layer");
245→            continue;
246→        }
247→
248→        let payload = BroadcastPayload {
249→            page_id: state.page_id.clone(),
250→            layer_name: layer_name.clone(),
251→            layer_type: domains::LayerType::from_layer_name(layer_name),
252→            update: data,
253→            state_vector,
254→        };
255→
256→        if let Err(e) = broadcast_tx.try_send(payload) {
257→            warn!(user_did = %user_did, layer = %layer_name, error = %e, "Failed to send initial state");
258→        } else {
259→            debug!(user_did = %user_did, layer = %layer_name, "Sent initial state");
260→        }
261→    }
262→}
