264→/// Bootstrap __sync_meta for a newly subscribed peer (node-side)
265→///
266→/// **Context**: After a peer subscribes, the node creates their __sync_meta layer,
267→/// populates it with static layer entries, adds existing dynamic layer entries
268→/// for late joiners, and subscribes the peer to their __sync_meta layer.
269→#[instrument(skip(state, broadcast_tx), fields(page_id = %state.page_id, peer_did = %peer_did))]
270→fn bootstrap_sync_meta(
271→    state: &mut ScribeState,
272→    peer_did: &str,
273→    peer_permit: &gurkha::Permit,
274→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
275→) {
276→    use super::sync_meta;
277→
278→    // 1. Create __sync_meta:{peer_did} layer
279→    let meta_layer_name = sync_meta::ensure_sync_meta_layer(state, peer_did);
280→
281→    // 2. Populate with static layer entries
282→    let is_owner = peer_permit.relationship() == Some("owner");
283→    sync_meta::populate_static_layers(state, peer_did, peer_permit, is_owner);
284→
285→    // 3. Populate dynamic layers for late joiners
286→    sync_meta::populate_dynamic_layers_for_late_joiner(state, peer_did);
287→
288→    // 4. Subscribe the peer to their __sync_meta layer so it syncs to them
289→    if let Some(unit) = state.units.get(&meta_layer_name) {
290→        let caps = Capabilities { read: true, write: true, sync: true };
291→        unit.add_subscriber(peer_did.to_string(), caps, broadcast_tx.clone());
292→        info!(
293→            layer = %meta_layer_name,
294→            peer_did = %peer_did,
295→            "Subscribed peer to their __sync_meta layer"
296→        );
297→    }
298→}
