 720→            ScribeMessage::HandleLayerSubscribe { layer_name, peer_did, reply } => {
 721→                let bare = crate::state::normalize_layer_name(&layer_name, &state.page_id);
 722→
 723→                // If layer doesn't exist but matches a dynamic schema, create it empty.
 724→                //
 725→                // **Context**: Timing race — __sync_meta broadcasts immediately (node is
 726→                // subscriber), but creator's dynamic layer data may not have synced yet.
 727→                // Peer discovers the entry in __sync_meta and sends LayerSubscribe before
 728→                // the layer exists on node. We create an empty layer; creator's data will
 729→                // arrive later via normal SyncOffer and broadcast to the now-subscribed peer.
 730→                if !state.units.contains_key(&bare) {
 731→                    if let Some(ref permit) = state.our_permit {
 732→                        if crate::layer_unit::find_matching_dynamic_schema(permit, &bare, &state.page_id).is_some() {
 733→                            info!(layer = %bare, "Creating empty dynamic layer for early LayerSubscribe");
 734→                            let mut unit = crate::layer_unit::LayerUnit::new_empty();
 735→                            unit.set_local_only(false);
 736→                            unit.is_dynamic = true;
 737→                            state.units.insert(bare.clone(), unit);
 738→                            crate::loro_observer::setup_layer_observer(state, &bare);
 739→                        }
 740→                    }
 741→                }
 742→
 743→                let result = (|| -> std::result::Result<(Vec<u8>, Vec<u8>, String), String> {
 744→                    let unit = state.units.get(&bare)
 745→                        .ok_or_else(|| format!("Layer '{}' not found", bare))?;
 746→
 747→                    // Issue permit via PermitIssuer
 748→                    let full_name = format!("{}/{}", state.page_id, bare);
 749→                    let permit_token = issue_layer_permit_for_subscribe(
 750→                        state, &peer_did, &bare, &full_name,
 751→                    )?;
 752→
 753→                    // Add peer as subscriber so they receive future broadcasts
 754→                    let mut subscriber_added = false;
 755→                    if let Ok(subs) = state.subscribers.read() {
 756→                        if let Some(sub_info) = subs.iter()
 757→                            .find(|((did, _), _)| did == &peer_did)
 758→                            .map(|(_, info)| info)
 759→                        {
 760→                            let caps = crate::layer_unit::Capabilities { read: true, write: true, sync: true };
 761→                            unit.add_subscriber(peer_did.clone(), caps, sub_info.broadcast_tx.clone());
 762→                            subscriber_added = true;
 763→                        }
 764→                    }
 765→
 766→                    state.emit_layer_subscribe_result_capture(
 767→                        &bare, &peer_did, "ok", None, subscriber_added,
 768→                    );
 769→
 770→                    let snapshot = unit.layer().export_snapshot();
 771→                    let state_vector = unit.layer().version_vector();
 772→                    Ok((snapshot, state_vector, permit_token))
 773→                })();
 774→
 775→                if let Err(ref e) = result {
 776→                    state.emit_layer_subscribe_result_capture(
 777→                        &bare, &peer_did, "err", Some(e), false,
 778→                    );
 779→                }
 780→                let _ = reply.send(result);
 781→            }
