 846→            ScribeMessage::SendStructuredEphemeral { func, args } => {
 847→                // Log the incoming request
 848→                let has_permit = state.our_permit.is_some();
 849→                let ephemeral_funcs = state.our_permit
 850→                    .as_ref()
 851→                    .map(|p| p.ephemeral_funcs().to_vec())
 852→                    .unwrap_or_default();
 853→                debug!(
 854→                    page_id = %state.page_id,
 855→                    func = %func,
 856→                    has_permit = has_permit,
 857→                    ephemeral_funcs = ?ephemeral_funcs,
