 859→                    "SendStructuredEphemeral received"
 860→                );
 861→
 862→                // Validate func against our permit's ephemeral_funcs (if set)
 863→                // Empty ephemeral_funcs list means all funcs allowed
 864→                let can_send = state.our_permit
 865→                    .as_ref()
 866→                    .map(|p| p.can_send_ephemeral(&func))
 867→                    .unwrap_or(true); // No permit = allow (local mode)
 868→
 869→                if !can_send {
 870→                    warn!(page_id = %state.page_id, func = %func, "Structured ephemeral func not allowed by permit");
 871→                    return Ok(());
 872→                }
 873→
 874→                // Broadcast as StructuredEphemeral to app subscribers (local UI)
 875→                let our_did = state.our_did.clone();
 876→                emit_structured_ephemeral(state, &our_did, &func, &args);
 877→
 878→                // Also broadcast via ephemeral channel for remote peers
 879→                // PeerActor should be subscribed to this Scribe with ephemeral_tx
 880→                // Include from_did so relayed messages preserve original sender identity
 881→                let payload = serde_json::json!({
 882→                    "type": "structured",
 883→                    "from_did": our_did,
 884→                    "func": func,
 885→                    "args": args
 886→                });
 887→                if let Ok(bytes) = serde_json::to_vec(&payload) {
 888→                    debug!(
 889→                        page_id = %state.page_id,
 890→                        func = %func,
 891→                        "Broadcasting structured ephemeral to PeerActor subscribers"
 892→                    );
 893→                    broadcast_ephemeral_to_subscribers(state, &bytes, None);
 894→                }
 895→            }
