 900→                    let subs = state.subscribers.read().ok();
 901→                    subs.and_then(|s| {
 902→                        s.get(&(from_did.clone(), device_id.clone()))
 903→                            .map(|info| info.permit.can_send_ephemeral(&func))
 904→                    }).unwrap_or(false) // Unknown sender = reject
 905→                };
 906→
 907→                if !can_send {
 908→                    warn!(
 909→                        page_id = %state.page_id,
 910→                        from_did = %from_did,
 911→                        func = %func,
 912→                        "Remote structured ephemeral rejected - func not allowed"
 913→                    );
 914→                    return Ok(());
 915→                }
 916→
 917→                // Emit to local app subscribers
 918→                emit_structured_ephemeral(state, &from_did, &func, &args);
 919→
 920→                debug!(
 921→                    page_id = %state.page_id,
 922→                    from_did = %from_did,
 923→                    func = %func,
 924→                    "Processed remote structured ephemeral"
 925→                );
 926→            }
 927→
 928→            // Note: Ephemeral events now go through SubscribeToPageUpdates (PageUpdate::Ephemeral)
 929→
 930→            // Derivation operations (now handled by kunki/LuaRuntime externally)
 931→            ScribeMessage::RebuildDerived { target: _, reply } => {
 932→                // Derivation is now handled by kunki, not Scribe
 933→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
 934→            }
 935→
 936→            ScribeMessage::RebuildAllDerived { reply } => {
 937→                // Derivation is now handled by kunki, not Scribe
 938→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
 939→            }
 940→
 941→            ScribeMessage::IsDerivationEnabled { reply } => {
 942→                // Derivation is now external, Scribe always returns false
 943→                let _ = reply.send(false);
 944→            }
 945→
 946→            ScribeMessage::CreateDerivedLayer { target_layer } => {
 947→                let target_layer = normalize_layer_name(&target_layer, &state.page_id);
 948→                // Create the derived layer (empty) so it exists for subscribers
 949→                if !state.units.contains_key(&target_layer) {
 950→                    let unit = LayerUnit::new_empty();
 951→                    let _ = unit.layer().loro().get_map(target_layer.clone());
 952→                    unit.layer().commit();
 953→                    state.units.insert(target_layer.clone(), unit);
 954→                    info!(target = %target_layer, "Created empty derived layer");
 955→
 956→                    // Set up observer for the new layer
 957→                    loro_observer::setup_layer_observer(state, &target_layer);
 958→                }
 959→            }
 960→
 961→            ScribeMessage::GetAppFiles { app_name, reply } => {
 962→                // Use bare layer name (Scribe uses bare names, no page_id/ prefix)
 963→                let layer_name = format!("app:{}", app_name);
 964→                let result = if let Some(unit) = state.units.get(&layer_name) {
 965→                    Ok(unit.layer().get_all_files())
 966→                } else {
 967→                    Err(format!("App layer '{}' not found", layer_name))
 968→                };
 969→                let _ = reply.send(result);
 970→            }
 971→
 972→            ScribeMessage::GetSubscriberCount { reply } => {
 973→                let count = state.subscribers.read()
 974→                    .map(|s| s.len())
 975→                    .unwrap_or(0);
 976→                let _ = reply.send(count);
 977→            }
 978→
 979→            ScribeMessage::RefreshApp { app_name: _, app_dir: _, reply } => {
 980→                // RefreshApp requires filesystem access which is handled by butler's refresh service
 981→                // This stub returns an error - callers should use butler's refresh functionality instead
 982→                let _ = reply.send(Err("RefreshApp not supported in base Scribe - use butler's refresh service".to_string()));
 983→            }
 984→        }
 985→
 986→        Ok(())
 987→    }
 988→
 989→    #[instrument(skip_all, fields(page_id = %state.page_id))]
 990→    async fn post_stop(
 991→        &self,
 992→        _myself: ActorRef<Self::Msg>,
 993→        state: &mut Self::State,
 994→    ) -> std::result::Result<(), ActorProcessingErr> {
 995→        // Flush any dirty layers before stopping
 996→        let has_dirty = state.units.values().any(|u| u.is_dirty());
 997→        if has_dirty {
 998→            let dirty_count = state.units.values().filter(|u| u.is_dirty()).count();
 999→            info!(page_id = %state.page_id, dirty_count = dirty_count, "Flushing dirty layers on shutdown");
1000→            sync::handle_flush(state).await;
1001→        }
1002→
1003→        // Stop node script if running
1004→        if let Some(tx) = state.node_script_shutdown.take() {
1005→            info!(page_id = %state.page_id, "Stopping node script tick loop");
1006→            let _ = tx.send(()).await;
1007→        }
1008→
1009→        info!(page_id = %state.page_id, "Scribe stopped");
1010→        Ok(())
1011→    }
1012→}
1013→
1014→// Helper Methods
1015→
1016→impl Scribe {
1017→    /// Handle JSON update from UI (CEL commit())
1018→    ///
1019→    /// **Broadcast**: Handled automatically by Loro observer after commit()
1020→    #[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
1021→    async fn handle_update_from_json(
1022→        &self,
1023→        state: &mut ScribeState,
1024→        layer_name: &str,
1025→        path: &str,
1026→        value: serde_json::Value,
1027→    ) -> Result<()> {
1028→        info!(layer = %layer_name, path = %path, "Updating layer from JSON");
1029→
1030→        // Get or create the layer unit
1031→        let unit = state
1032→            .units
1033→            .entry(layer_name.to_string())
1034→            .or_insert_with(LayerUnit::new_empty);
1035→
1036→        // Convert JSON to Loro and update
1037→        unit.layer()
1038→            .set_from_json(path, &value)
1039→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
1040→
1041→        // Commit to trigger Loro observer (which broadcasts to peers + notifies UI)
1042→        unit.layer().commit();
1043→
1044→        // Mark as dirty for persistence
1045→        unit.mark_dirty();
1046→
1047→        debug!("Layer update from JSON complete, observer will broadcast");
1048→        Ok(())
1049→    }
1050→}
1051→
1052→/// Issue a layer permit for a LayerSubscribe request
1053→///
1054→/// **Context**: Peer sent LayerSubscribe, we need to issue a permit.
1055→/// Permit-driven priority:
1056→/// 1. Self-permit check: I'm the creator → issue authority permit
1057→/// 2. Stored authority check: I'm the node → issue layer_permit
1058→/// 3. Static layer: defined in our permit → issue layer_permit
1059→fn issue_layer_permit_for_subscribe(
1060→    state: &ScribeState,
1061→    peer_did: &str,
1062→    bare_layer_name: &str,
1063→    full_layer_name: &str,
1064→) -> std::result::Result<String, String> {
1065→    let issuer = state.permit_issuer.as_ref()
1066→        .ok_or_else(|| {
1067→            state.emit_permit_issue_capture(full_layer_name, peer_did, "none", "err", Some("no permit issuer"));
1068→            "No permit issuer (not node mode)".to_string()
1069→        })?;
1070→
1071→    // 1. Self-permit check: I'm the creator
1072→    // If we have a self-permit for this layer, issue authority permit to requester (node)
1073→    match issuer.get_layer_authority_permit(&state.our_did, full_layer_name) {
1074→        Ok(Some((_version, self_authority_token))) => {
1075→            // Parse self-permit to get authorized_peers and config
1076→            if let Ok(self_permit) = gurkha::Permit::from_token(&self_authority_token) {
1077→                let authorized_peers = self_permit.get_fact("authorized_peers")
1078→                    .and_then(|v| {
1079→                        v.as_array().map(|arr| {
1080→                            arr.iter()
1081→                                .filter_map(|v| v.as_str().map(String::from))
1082→                                .collect::<Vec<_>>()
1083→                        })
1084→                    });
1085→                let config = self_permit.layers().get(full_layer_name)
1086→                    .or_else(|| self_permit.layers().get(bare_layer_name))
1087→                    .cloned()
1088→                    .unwrap_or(gurkha::LayerConfig { sync: true, write: true, layer_type: None });
1089→
1090→                match issuer.issue_layer_authority_permit(
1091→                    peer_did, full_layer_name, config, authorized_peers, _version + 1,
1092→                ) {
1093→                    Ok((token, _cid)) => {
1094→                        info!(layer = %full_layer_name, peer = %peer_did, "Issued authority permit (creator → node)");
1095→                        state.emit_permit_issue_capture(full_layer_name, peer_did, "self_permit", "ok", None);
1096→                        return Ok(token);
1097→                    }
1098→                    Err(e) => {
1099→                        warn!(error = %e, "Failed to issue authority permit from self-permit");
1100→                        state.emit_permit_issue_capture(full_layer_name, peer_did, "self_permit", "err", Some(&e.to_string()));
1101→                    }
1102→                }
1103→            }
1104→        }
1105→        Ok(None) => {
1106→            state.emit_permit_issue_capture(full_layer_name, peer_did, "self_permit", "skip", Some("no self-permit found"));
1107→        }
1108→        Err(e) => {
1109→            warn!(error = %e, "Error looking up self-permit");
1110→            state.emit_permit_issue_capture(full_layer_name, peer_did, "self_permit", "err", Some(&e.to_string()));
1111→        }
1112→    }
1113→
1114→    // 2. Stored authority check: I'm the node with authority from a creator
1115→    match issuer.get_authority_for_layer(bare_layer_name) {
1116→        Ok(Some((_creator_did, _version, authority_token))) => {
1117→            // Parse authority to check authorized_peers
1118→            if let Ok(authority_permit) = gurkha::Permit::from_token(&authority_token) {
1119→                let authorized_peers = authority_permit.get_fact("authorized_peers");
1120→                let is_authorized = match authorized_peers {
1121→                    None => true, // No authorized_peers fact → open grant
1122→                    Some(serde_json::Value::Null) => true, // Explicit null → open grant
1123→                    Some(serde_json::Value::Array(arr)) => {
1124→                        arr.iter().any(|v| v.as_str() == Some(peer_did))
1125→                    }
1126→                    _ => false,
1127→                };
1128→
1129→                if is_authorized {
1130→                    let config = authority_permit.layers().get(full_layer_name)
1131→                        .or_else(|| authority_permit.layers().get(bare_layer_name))
1132→                        .cloned()
1133→                        .unwrap_or(gurkha::LayerConfig { sync: true, write: true, layer_type: None });
1134→
1135→                    let intent_cid = gurkha::crypto::get_permit_cid(&authority_token).ok();
1136→                    match issuer.issue_layer_permit(
1137→                        peer_did, full_layer_name, config, intent_cid.as_deref(),
1138→                    ) {
1139→                        Ok((token, _cid)) => {
1140→                            info!(layer = %full_layer_name, peer = %peer_did, "Issued layer permit from stored authority");
1141→                            state.emit_permit_issue_capture(full_layer_name, peer_did, "stored_authority", "ok", None);
1142→                            return Ok(token);
1143→                        }
1144→                        Err(e) => {
1145→                            warn!(error = %e, "Failed to issue permit from stored authority");
1146→                            state.emit_permit_issue_capture(full_layer_name, peer_did, "stored_authority", "err", Some(&e.to_string()));
1147→                        }
1148→                    }
1149→                } else {
1150→                    warn!(layer = %full_layer_name, peer = %peer_did, "Peer not in authorized_peers list");
1151→                    state.emit_permit_issue_capture(full_layer_name, peer_did, "stored_authority", "err", Some("peer not in authorized_peers"));
1152→                }
1153→            }
1154→        }
1155→        Ok(None) => {
1156→            state.emit_permit_issue_capture(full_layer_name, peer_did, "stored_authority", "skip", Some("no authority found"));
1157→        }
1158→        Err(e) => {
1159→            warn!(error = %e, "Error looking up authority for layer");
1160→            state.emit_permit_issue_capture(full_layer_name, peer_did, "stored_authority", "err", Some(&e.to_string()));
1161→        }
1162→    }
1163→
1164→    // 3. Static layer from our own permit
1165→    if let Some(ref our_permit) = state.our_permit {
1166→        if let Some(config) = our_permit.layers().get(full_layer_name) {
1167→            match issuer.issue_layer_permit(peer_did, full_layer_name, config.clone(), None) {
1168→                Ok((token, _cid)) => {
1169→                    state.emit_permit_issue_capture(full_layer_name, peer_did, "static_layer", "ok", None);
1170→                    return Ok(token);
1171→                }
1172→                Err(e) => {
1173→                    warn!(error = %e, layer = %full_layer_name, "Failed to issue permit for static layer");
1174→                    state.emit_permit_issue_capture(full_layer_name, peer_did, "static_layer", "err", Some(&e.to_string()));
1175→                }
1176→            }
1177→        } else {
1178→            state.emit_permit_issue_capture(full_layer_name, peer_did, "static_layer", "skip", Some("layer not in our permit"));
1179→        }
1180→    }
1181→
1182→    state.emit_permit_issue_capture(full_layer_name, peer_did, "none", "err", Some("all paths exhausted"));
1183→    Err(format!("Cannot issue layer permit for {} to {}", full_layer_name, peer_did))
1184→}
1185→
1186→/// Handle StoreLayerAuthority message (node-side)
1187→///
1188→/// **Context**: Node received authority from creator via LayerSubscribeAck.
1189→/// **We do**: Store authority, apply layer data, fan out to authorized peers.
1190→fn handle_store_layer_authority(
1191→    state: &mut ScribeState,
1192→    layer_name: &str,
1193→    creator_did: &str,
1194→    authority_token: &str,
1195→    layer_data: &[u8],
1196→) {
1197→    let bare = crate::state::normalize_layer_name(layer_name, &state.page_id);
1198→
1199→    // 1. Store authority permit via PermitIssuer
1200→    if let Some(ref issuer) = state.permit_issuer {
1201→        if let Err(e) = issuer.store_authority_permit(creator_did, layer_name, authority_token, 1) {
1202→            error!(layer = %layer_name, error = %e, "Failed to store authority permit");
1203→            return;
1204→        }
1205→        info!(layer = %layer_name, creator = %creator_did, "Stored authority permit from creator");
1206→    }
1207→
1208→    // 2. Create LayerUnit if needed and apply layer data
1209→    if !state.units.contains_key(&bare) {
1210→        let mut unit = LayerUnit::new_empty();
1211→        unit.set_local_only(false);
1212→        unit.is_dynamic = true;
1213→        state.units.insert(bare.clone(), unit);
1214→        loro_observer::setup_layer_observer(state, &bare);
1215→        info!(layer = %bare, "Created dynamic layer from authority");
1216→    }
1217→
1218→    if !layer_data.is_empty() {
1219→        if let Some(unit) = state.units.get(&bare) {
1220→            if let Err(e) = unit.layer().apply(layer_data) {
1221→                warn!(layer = %bare, error = %e, "Failed to apply layer data from authority");
1222→            } else {
1223→                unit.layer().commit();
1224→                if let Some(unit) = state.units.get_mut(&bare) {
1225→                    unit.mark_dirty();
1226→                }
1227→            }
1228→        }
1229→    }
1230→
1231→    // 3. Parse authorized_peers from authority and fan out
1232→    if let Ok(authority_permit) = gurkha::Permit::from_token(authority_token) {
1233→        let authorized_peers = authority_permit.get_fact("authorized_peers")
1234→            .and_then(|v| match v {
1235→                serde_json::Value::Null => None,
1236→                serde_json::Value::Array(arr) => Some(
1237→                    arr.iter()
1238→                        .filter_map(|v| v.as_str().map(String::from))
1239→                        .collect::<Vec<_>>()
1240→                ),
1241→                _ => None,
1242→            });
1243→
1244→        handle_fan_out_layer_to_users(state, &bare, authorized_peers.as_deref());
1245→    }
1246→
1247→    // 4. Mark creator's __sync_meta entry as synced
1248→    sync::sync_meta::mark_entry_synced(state, creator_did, &bare);
1249→}
1250→
1251→/// Fan out a layer entry to authorized users' __sync_meta
1252→///
1253→/// **Context**: Node needs to notify authorized peers about a new dynamic layer.
1254→/// **authorized_peers**: None = all subscribers, Some(list) = specific DIDs only.
1255→fn handle_fan_out_layer_to_users(
1256→    state: &mut ScribeState,
1257→    layer_name: &str,
1258→    authorized_peers: Option<&[String]>,
1259→) {
1260→    // Collect all subscriber DIDs
1261→    let all_peer_dids: Vec<String> = {
1262→        let mut dids = Vec::new();
1263→        if let Ok(subs) = state.subscribers.read() {
1264→            for ((did, _), _) in subs.iter() {
1265→                if !dids.contains(did) {
1266→                    dids.push(did.clone());
1267→                }
1268→            }
1269→        }
1270→        dids
1271→    };
1272→
1273→    let target_dids: Vec<&String> = match authorized_peers {
1274→        None => all_peer_dids.iter().collect(),
1275→        Some(list) => all_peer_dids.iter()
1276→            .filter(|did| list.iter().any(|d| d == *did))
1277→            .collect(),
1278→    };
1279→
1280→    for peer_did in target_dids {
1281→        let peer_entries = sync::sync_meta::read_sync_meta_entries(state, peer_did);
1282→        let already_has = peer_entries.iter().any(|e| e.layer_name == layer_name);
1283→        if !already_has {
1284→            sync::sync_meta::write_sync_meta_entry(state, peer_did, layer_name, false);
1285→            info!(
1286→                layer = %layer_name,
1287→                peer_did = %peer_did,
1288→                "Fan out: wrote dynamic entry to peer's __sync_meta"
1289→            );
1290→        }
1291→    }
1292→}
1293→
1294→// Tests
1295→
1296→#[cfg(test)]
1297→mod tests {
1298→    use super::*;
1299→    use crate::test_fixtures::node_scribe_args;
1300→    use std::time::Duration;
1301→
1302→    /// Test that Scribe with no subscribers doesn't crash on ephemeral send
1303→    #[tokio::test]
1304→    async fn test_ephemeral_with_no_subscribers() {
1305→        let args = node_scribe_args("test-page-456");
1306→        let (scribe_ref, _handle) = ractor::Actor::spawn(
1307→            Some("test-scribe-no-subs".to_string()),
1308→            Scribe,
1309→            args,
1310→        ).await.expect("Failed to spawn Scribe");
1311→
1312→        // Send ephemeral with no subscribers - should not crash
1313→        scribe_ref.cast(ScribeMessage::SendStructuredEphemeral {
1314→            func: "typing".to_string(),
1315→            args: serde_json::json!({"user": "TestUser"}),
1316→        }).expect("Failed to send ephemeral");
1317→
1318→        // Small delay to ensure message is processed
1319→        tokio::time::sleep(Duration::from_millis(50)).await;
1320→
1321→        println!("✓ Ephemeral with no subscribers handled gracefully");
1322→        scribe_ref.stop(Some("test complete".to_string()));
1323→    }
1324→}
