// Write entry to creator's __sync_meta for node discovery
//
// **Race fix**: The __sync_meta layer may not exist yet if the node hasn't
// bootstrapped it back to us. Eagerly create it and add subscribers so the
// observer broadcast reaches the sync target (node).
{
    use crate::sync::sync_meta;
    let our_did = state.our_did.clone();
    let meta_layer = sync_meta::sync_meta_layer_name(&our_did);
    let was_new = !state.units.contains_key(&meta_layer);
    if was_new {
        sync_meta::ensure_sync_meta_layer(state, &our_did);
        // Add all connected subscribers so observer broadcast reaches the node
        if let Ok(subs) = state.subscribers.read() {
